import {useLayoutEffect,useRef} from "react";
import {Platform,Text,View,type ViewProps} from "react-native";
import {SelectionOutline} from "@/components/nyc-tron/ui/components/forge/selection/SelectionOutline";
import {useLocalPointer} from "@/components/nyc-tron/ui/components/gestures/useLocalPointer";
import {webKey} from "@/components/nyc-tron/ui/components/forms/choice-keys";
import {useLocalStore} from "@/components/nyc-tron/ui/components/useLocalStore";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {docPointToScreen,screenPointToDoc,tidy,validateViewport,type CanvasViewport,type DocPoint} from "@/components/nyc-tron/ui/components/forge/canvas/canvas-viewport";
import {
  ANCHOR_SNAP_RADIUS,ORIGIN_ANCHORS,ORIGIN_ANCHOR_LABELS,anchorPoint,currentAnchor,cycleAnchor,nearestAnchor,
  originAccessibilityValue,originKeyCommand,originPayload,pivotInDoc,validateTransform,
  type BoundsCorners,type LayerTransform,type OriginAnchor,
} from "@/components/nyc-tron/ui/components/forge/canvas/transform-origin-model";
import {space,radius,opacity} from "@/components/nyc-tron/ui/tokens";

/** Props for {@linkcode TransformOriginHandle}. */
export interface TransformOriginHandleProps extends Omit<ViewProps,"children"> {
  /** Hide the shared outline/anchor ink when composing with SelectionBounds. */
  readonly showBounds?:boolean;
  readonly scope?:string;
  readonly revision?:string|number;
  readonly viewport:CanvasViewport;
  /** Document corners of the selection's transformed bounds (`layerBounds` `corners`, or `rectCorners` of its box). */
  readonly corners:BoundsCorners;
  /** The one selected layer's transform. Omit, with `unavailableReason`, when the pivot cannot be edited. */
  readonly transform?:LayerTransform;
  /**
   * Shown at the selection's centre instead of a handle, e.g. "Select one
   * layer to move its pivot" for a multi-selection or "Unlock the layer to
   * move its pivot". Required when `transform` is omitted.
   */
  readonly unavailableReason?:string;
  /**
   * The pivot was dropped or stepped to a new spot. `ox`/`oy` are content
   * coordinates, ready for `setTransformOrigin {id, ox, oy}`. One call per
   * release or key press.
   */
  readonly onSetOrigin:(ox:number,oy:number)=>void;
  /** Document point under the dragged pivot on each move, then `undefined` when the drag ends or is cancelled. */
  readonly onPreview?:(point:DocPoint|undefined)=>void;
  readonly disabled?:boolean;
  className?:string;
  unstyled?:boolean;
}

type Local={drag:{at:DocPoint;anchor:OriginAnchor|undefined}|undefined};
const NO_SELECT=(Platform.OS==="web"?{userSelect:"none",touchAction:"none"}:{}) as object;
const HIT=44;

/**
 * Pivot editor for one layer (B-08). Draws the selection's bounds with its
 * nine anchors and a draggable pivot; within 12 units of an anchor the pivot
 * lands on it exactly. Release commits once through `onSetOrigin` in content
 * coordinates, and Prism shifts the translation so the layer does not move.
 * With keyboard focus, arrows move the pivot one document pixel (ten with
 * Shift) and keys 1 to 9 jump to the anchors in numeric-keypad layout;
 * screen readers step through the anchors. Escape cancels a drag. For
 * rotation drags around the pivot, use `rotationFromDrag` from the model,
 * which snaps to 15° with Shift.
 */
export function TransformOriginHandle({
  showBounds=true,scope="canvas-pivot",revision=0,viewport,corners,transform,unavailableReason,onSetOrigin:commitOrigin,onPreview:previewOrigin,disabled=false,className,unstyled=false,style,...rest
}:TransformOriginHandleProps){
  validateViewport(viewport);
  if(!scope.trim()||scope.length>512||typeof revision==='number'&&!Number.isFinite(revision)||typeof revision==='string'&&revision.length>512)throw new RangeError('Invalid pivot identity');
  if(corners.length!==4||corners.some(c=>c.length!==2||!c.every(Number.isFinite)))throw new RangeError('Pivot bounds need four finite corners');
  const boundary=JSON.stringify([scope,revision,viewport,corners,transform,disabled]);
  const mounted=useRef(false),committed=useRef(boundary);
  useLayoutEffect(()=>{mounted.current=true;return()=>{mounted.current=false;};},[]);
  useLayoutEffect(()=>{committed.current=boundary;});
  const valid=()=>mounted.current&&committed.current===boundary&&!disabled;
  const onSetOrigin=(ox:number,oy:number)=>{if(valid())commitOrigin(ox,oy);};
  const onPreview=(point:DocPoint|undefined)=>{if(valid())previewOrigin?.(point);};
  if(transform)validateTransform(transform);
  else if(!unavailableReason?.trim())throw new RangeError("TransformOriginHandle needs a transform, or an unavailableReason saying why there is none");
  const [state,store]=useLocalStore<Local>(()=>({drag:undefined}));
  useLayoutEffect(()=>{store.set({drag:undefined});},[boundary]);
  const styled=!unstyled;
  const screenCorners=corners.map(c=>docPointToScreen(viewport,{x:c[0],y:c[1]}));
  const center=docPointToScreen(viewport,anchorPoint(corners,"center"));
  const pivotDoc=state.drag?.at??(transform?pivotInDoc(transform):anchorPoint(corners,"center"));
  const pivot=docPointToScreen(viewport,pivotDoc);
  const handleLeft=pivot.x-HIT/2,handleTop=pivot.y-HIT/2;
  // The handle moves under the pointer while dragging; local points are measured
  // from where it was when the press began.
  const start=useRef({left:handleLeft,top:handleTop});
  const commitAt=(doc:DocPoint)=>{
    if(!valid()||!transform)return;
    const now=pivotInDoc(transform);
    if(Math.abs(now.x-doc.x)<1e-6&&Math.abs(now.y-doc.y)<1e-6)return;
    const {ox,oy}=originPayload(transform,doc);
    onSetOrigin(ox,oy);
  };
  const place=(local:{x:number;y:number})=>{
    const doc=screenPointToDoc(viewport,{x:start.current.left+local.x,y:start.current.top+local.y});
    const anchor=nearestAnchor(corners,doc,ANCHOR_SNAP_RADIUS/viewport.zoom);
    return {at:anchor?anchorPoint(corners,anchor):{x:tidy(doc.x,2),y:tidy(doc.y,2)},anchor};
  };
  const cancel=()=>{if(store.get().drag){store.set({drag:undefined});onPreview?.(undefined);}};
  const handlers=useLocalPointer({
    disabled:disabled||!transform,
    onBegin:p=>{if(!valid())return;start.current={left:handleLeft,top:handleTop};
      const d=place(p);store.set({drag:d});onPreview?.(d.at);},
    onMove:p=>{if(!valid()||!store.get().drag)return;const d=place(p);store.set({drag:d});onPreview?.(d.at);},
    onRelease:p=>{if(!valid()||!store.get().drag)return;const d=place(p);store.set({drag:undefined});onPreview?.(undefined);commitAt(d.at);},
    onCancel:cancel,
  });
  const onKeyDown=(event:unknown)=>{
    const k=webKey(event);
    if(k.key==="Escape"){cancel();return;}
    if(!valid()||!transform)return;
    const cmd=originKeyCommand(k.key,k.shiftKey===true);
    if(!cmd)return;
    k.preventDefault();
    if(cmd.kind==="anchor")commitAt(anchorPoint(corners,cmd.anchor));
    else{const p=pivotInDoc(transform);commitAt({x:tidy(p.x+cmd.dx),y:tidy(p.y+cmd.dy)});}
  };
  const anchorNow=transform?currentAnchor(corners,transform):undefined;
  const step=(direction:1|-1)=>commitAt(anchorPoint(corners,cycleAnchor(anchorNow,direction)));
  const dragAnchor=state.drag?.anchor;
  return <View {...rest} pointerEvents="box-none" {...{className:joinClasses(className)}}
    style={[{position:"absolute",left:0,top:0,width:viewport.width,height:viewport.height,overflow:"hidden",direction:"ltr"},style]}>
    {showBounds?<View pointerEvents="none" style={{position:"absolute",left:0,top:0,right:0,bottom:0}}>
      <SelectionOutline points={screenCorners} width={viewport.width} height={viewport.height} unstyled={unstyled}/>
      {ORIGIN_ANCHORS.map(anchor=>{
        const p=docPointToScreen(viewport,anchorPoint(corners,anchor));
        const hot=dragAnchor===anchor;
        return <View key={anchor} {...{className:joinClasses(styled&&"border",styled&&(hot?"bg-primary border-primary":"bg-surface-raised border-primary"))}}
          style={{position:"absolute",left:p.x-(hot?5:4),top:p.y-(hot?5:4),width:hot?10:8,height:hot?10:8}}/>;
      })}
    </View>:null}
    {transform?<View {...handlers} collapsable={false}
      accessible accessibilityRole="adjustable" accessibilityLabel="Pivot"
      accessibilityHint="Drag to move the point the layer rotates and scales around. Arrow keys nudge it; keys 1 to 9 jump to the anchors."
      aria-valuetext={state.drag?(state.drag.anchor?`Pivot at ${ORIGIN_ANCHOR_LABELS[state.drag.anchor]}`:"Pivot moving"):originAccessibilityValue(corners,transform)}
      accessibilityActions={disabled?[]:[{name:"increment",label:"Next anchor"},{name:"decrement",label:"Previous anchor"},{name:"center",label:"Center the pivot"}]}
      onAccessibilityAction={e=>{
        const a=e.nativeEvent.actionName;
        if(a==="increment")step(1);else if(a==="decrement")step(-1);else if(a==="center")commitAt(anchorPoint(corners,"center"));
      }}
      aria-disabled={disabled}
      {...{onKeyDown,focusable:!disabled,className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
      style={{position:"absolute",left:handleLeft,top:handleTop,width:HIT,height:HIT,alignItems:"center",justifyContent:"center",
        opacity:disabled?opacity[50]:1,...NO_SELECT}}>
      <View pointerEvents="none" style={{width:22,height:22,alignItems:"center",justifyContent:"center"}}>
        <View {...{className:joinClasses(styled&&"bg-primary")}} style={{position:"absolute",width:22,height:2}}/>
        <View {...{className:joinClasses(styled&&"bg-primary")}} style={{position:"absolute",width:2,height:22}}/>
        <View {...{className:joinClasses(styled&&"border-2",styled&&(state.drag?"border-accent bg-surface-raised":"border-primary bg-surface-raised"))}}
          style={{width:12,height:12,borderRadius:radius[6]}}/>
      </View>
    </View>:null}
    {!transform&&unavailableReason?<View pointerEvents="none" style={{position:"absolute",left:Math.max(4,Math.min(center.x-110,viewport.width-224)),top:center.y-14,width:220,alignItems:"center"}}>
      <Text accessibilityLiveRegion="polite"
        {...{className:joinClasses(styled&&"bg-surface-raised border border-border rounded-control text-text text-xs")}}
        style={{paddingHorizontal:space[2],paddingVertical:space[1],textAlign:"center"}}>{unavailableReason}</Text>
    </View>:null}
  </View>;
}

import {View} from 'react-native';
import type {DocPoint} from '@/components/nyc-tron/ui/components/forge/canvas/canvas-viewport';
import {joinClasses} from '@/components/nyc-tron/ui/components/styles';
/** Shared selection outline owner. Clip line geometry before creating native views. */
export function SelectionOutline({points,width,height,unstyled=false}:{points:readonly DocPoint[];width:number;height:number;unstyled?:boolean}){
 return <>{points.map((point,index)=>{const end=points[(index+1)%points.length]!,line=clip(point,end,width,height);if(!line)return null;const [a,b]=line,length=Math.hypot(b.x-a.x,b.y-a.y),angle=Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI;return <View key={index} pointerEvents="none" {...{className:joinClasses(!unstyled&&'bg-primary')}} style={{position:'absolute',left:(a.x+b.x-length)/2,top:(a.y+b.y)/2-.5,width:length,height:1,transform:[{rotate:angle+'deg'}]}}/>;})}</>;
}
function clip(a:DocPoint,b:DocPoint,width:number,height:number):readonly[DocPoint,DocPoint]|null{
 const dx=b.x-a.x,dy=b.y-a.y;let from=0,to=1;
 for(const [p,q] of [[-dx,a.x],[dx,width-a.x],[-dy,a.y],[dy,height-a.y]] as const){if(p===0){if(q<0)return null;continue;}const ratio=q/p;if(p<0)from=Math.max(from,ratio);else to=Math.min(to,ratio);if(from>to)return null;}
 return [{x:a.x+from*dx,y:a.y+from*dy},{x:a.x+to*dx,y:a.y+to*dy}];
}

import {createContext,useRef} from 'react';
/** Invalidate ephemeral gestures without remounting focused controls or product state. */
export const EditorInteractionScope=createContext<string|null>(null);
let nextInstance=0;
/** Compare cached document signatures by identity without reserializing a whole
 * timeline on every playback tick or nesting its data in child scope strings. */
export function useEditorBoundary(parts:readonly unknown[]):string{
 const ref=useRef<{id:number;version:number;parts:readonly unknown[]}|null>(null);
 ref.current??={id:++nextInstance,version:0,parts:[]};
 const current=ref.current;
 if(parts.length!==current.parts.length||parts.some((part,index)=>!Object.is(part,current.parts[index]))){current.parts=[...parts];current.version++;}
 return current.id+':'+current.version;
}

import type {GestureResponderEvent,PanResponderCallbacks} from "react-native";

/** A point in the responder view's own coordinates (0,0 is its top-left corner). */
export interface LocalPoint {
  readonly x:number;
  readonly y:number;
  /**
   * Touch or stylus force 0..1 when the platform reports one (iOS touches and
   * Apple Pencil, Android styluses). Absent for mice and for touch screens
   * that report no force.
   */
  readonly pressure?:number;
}
/**
 * Callbacks for {@linkcode localPointerConfig}. Unlike `DragTransport`, which reports
 * page coordinates, these report points inside the view, for controls that map a
 * position to a value (a color disc, a seek bar, a clip edge).
 */
export interface LocalPointerHandlers {
  readonly disabled?:boolean;
  onBegin(point:LocalPoint):void;
  onMove(point:LocalPoint):void;
  onRelease(point:LocalPoint):void;
  /** OS termination, or a second pointer when {@linkcode LocalPointerHandlers.onPinch} is absent. */
  onCancel():void;
  /**
   * Two-pointer pinch. `scale` is the current pointer distance over the distance when
   * the second pointer landed; `center` is their midpoint. Once a pinch starts, the
   * gesture ends with {@linkcode LocalPointerHandlers.onPinchEnd} instead of a release.
   */
  onPinch?(scale:number,center:LocalPoint):void;
  onPinchEnd?():void;
}

type Latest={readonly current:LocalPointerHandlers};

const withForce=(point:{x:number;y:number},force:number|undefined):LocalPoint=>
  typeof force==="number"&&Number.isFinite(force)&&force>0?{...point,pressure:Math.min(1,force)}:point;
type Touch={readonly pageX:number;readonly pageY:number};

/**
 * PanResponder callbacks that report view-local points. The grant point is
 * `locationX/Y`, which is relative to the touched view, so every child of the
 * responder view must set `pointerEvents="none"`. Later points add the page-space
 * travel to the grant point; `locationX` on a move would be measured from whatever
 * view the pointer is over.
 */
export function localPointerConfig(latest:Latest):PanResponderCallbacks{
  let origin={x:0,y:0,pageX:0,pageY:0};
  let pinch:{distance:number}|undefined;
  let live=false;
  const local=(pageX:number,pageY:number,force?:number):LocalPoint=>withForce({x:origin.x+pageX-origin.pageX,y:origin.y+pageY-origin.pageY},force);
  const touchesOf=(event:GestureResponderEvent):readonly Touch[]=>event.nativeEvent.touches??[];
  const end=()=>{live=false;pinch=undefined;};
  return {
    onStartShouldSetPanResponder:()=>!latest.current.disabled,
    onMoveShouldSetPanResponder:()=>!latest.current.disabled,
    onPanResponderGrant:event=>{
      const n=event.nativeEvent;
      origin={x:n.locationX,y:n.locationY,pageX:n.pageX,pageY:n.pageY};
      pinch=undefined;
      live=true;
      latest.current.onBegin(withForce({x:n.locationX,y:n.locationY},n.force));
    },
    onPanResponderMove:event=>{
      if(!live)return;
      const touches=touchesOf(event);
      if(touches.length>=2){
        const handlers=latest.current;
        if(!handlers.onPinch){end();handlers.onCancel();return;}
        const [a,b]=touches as [Touch,Touch];
        const distance=Math.hypot(b.pageX-a.pageX,b.pageY-a.pageY);
        if(!pinch){
          // The one-pointer gesture that started this is abandoned, not committed.
          handlers.onCancel();
          pinch={distance:Math.max(distance,1)};
        }
        handlers.onPinch(distance/pinch.distance,local((a.pageX+b.pageX)/2,(a.pageY+b.pageY)/2));
        return;
      }
      if(pinch)return;
      latest.current.onMove(local(event.nativeEvent.pageX,event.nativeEvent.pageY,event.nativeEvent.force));
    },
    onPanResponderRelease:event=>{
      if(!live)return;
      const pinched=pinch!==undefined;
      end();
      if(pinched)latest.current.onPinchEnd?.();
      else latest.current.onRelease(local(event.nativeEvent.pageX,event.nativeEvent.pageY));
    },
    // A parent ScrollView must not take a granted drag; the OS still can.
    onPanResponderTerminationRequest:()=>false,
    onPanResponderTerminate:()=>{
      if(!live)return;
      const pinched=pinch!==undefined;
      end();
      if(pinched)latest.current.onPinchEnd?.();
      else latest.current.onCancel();
    },
    onShouldBlockNativeResponder:()=>true,
  };
}

import {useContext,useLayoutEffect,useMemo,useRef} from "react";
import {PanResponder,type GestureResponderEvent,type GestureResponderHandlers,type PanResponderGestureState,type PanResponderCallbacks} from "react-native";
import {localPointerConfig,type LocalPointerHandlers} from "@/components/nyc-tron/ui/components/gestures/local-pointer";
import {EditorInteractionScope} from '@/components/nyc-tron/ui/components/gestures/editor-interaction-scope';

/**
 * Responder handlers for one view, built once and fed the latest callbacks on
 * every event. Spread the result on the view that defines the local coordinate
 * space; see {@linkcode localPointerConfig} for the `pointerEvents` rule.
 */
export function useLocalPointer(handlers:LocalPointerHandlers):GestureResponderHandlers{
  const scope=useContext(EditorInteractionScope);
  const latest=useRef(handlers);
  useLayoutEffect(()=>{latest.current=handlers;});
  const owner=useRef<{active:boolean;blocked:boolean;last:[GestureResponderEvent,PanResponderGestureState]|null}>({active:false,blocked:false,last:null});
  const config=useMemo<PanResponderCallbacks>(()=>localPointerConfig(latest),[]);
  const cancel=()=>{const s=owner.current;owner.current={active:false,blocked:true,last:null};if(s.active&&s.last)config.onPanResponderTerminate?.(...s.last);};
  useLayoutEffect(()=>{if(scope!==null)cancel();return()=>{if(scope!==null)cancel();};},[scope]);
  return useMemo(()=>PanResponder.create({
    ...config,
    onStartShouldSetPanResponder:(...args)=>{owner.current.blocked=false;return config.onStartShouldSetPanResponder?.(...args)??false;},
    onMoveShouldSetPanResponder:(...args)=>!owner.current.blocked&&(config.onMoveShouldSetPanResponder?.(...args)??false),
    onPanResponderGrant:(...args)=>{owner.current={active:true,blocked:false,last:args};config.onPanResponderGrant?.(...args);},
    onPanResponderMove:(...args)=>{if(!owner.current.active)return;owner.current.last=args;config.onPanResponderMove?.(...args);},
    onPanResponderRelease:(...args)=>{if(!owner.current.active)return;owner.current.active=false;owner.current.last=null;config.onPanResponderRelease?.(...args);},
    onPanResponderTerminate:(...args)=>{if(!owner.current.active)return;owner.current.active=false;owner.current.last=null;config.onPanResponderTerminate?.(...args);},
  }).panHandlers,[config]);
}

import {createStore} from "zustand/vanilla";

/**
 * A per-instance store for transient gesture and draft state (a drag preview, a
 * text draft, a measured width). Components use it instead of `useState` so a
 * gesture's bookkeeping lives outside React's render cycle and can be read
 * synchronously from responder callbacks. Created by {@linkcode createLocalStore};
 * components use it through `useLocalStore`. Zustand owns the state; this value-replacement
 * adapter remains independent of React.
 */
export interface LocalStore<T> {
  get():T;
  /** Replaces the state, or derives it from the previous state. Listeners run only when it changes. */
  set(next:T|((previous:T)=>T)):void;
  /** Returns the unsubscribe function. */
  subscribe(listener:()=>void):()=>void;
}

/** Creates a {@linkcode LocalStore}. Equal states (by `Object.is`) do not notify. */
export function createLocalStore<T>(initial:T):LocalStore<T>{
  const store=createStore<{value:T}>(()=>({value:initial}));
  return {
    get:()=>store.getState().value,
    set(next){
      store.setState(current=>{
        const value=typeof next==="function"?(next as (p:T)=>T)(current.value):next;
        return Object.is(value,current.value)?current:{value};
      });
    },
    subscribe(listener){return store.subscribe(()=>listener());},
  };
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

import {useRef,useSyncExternalStore} from "react";
import {createLocalStore,type LocalStore} from "@/components/nyc-tron/ui/components/local-store";

/**
 * Creates one {@linkcode LocalStore} for the calling component on first render and
 * subscribes to it. Returns the current state and the store.
 */
export function useLocalStore<T>(initial:()=>T):readonly [T,LocalStore<T>]{
  const ref=useRef<LocalStore<T>|null>(null);
  if(!ref.current)ref.current=createLocalStore(initial());
  const store=ref.current;
  const state=useSyncExternalStore(store.subscribe,store.get,store.get);
  return [state,store] as const;
}

